from pathlib import Path
import re

path = Path('site/index.html')
html = path.read_text(encoding='utf-8')

hero_css = """
.heroVisual .heroPhoto{position:absolute;inset:0;width:100%;height:100%;object-fit:cover;object-position:center center;display:block}
.heroVisual:after{content:"";position:absolute;inset:0;background:linear-gradient(180deg,rgba(3,9,18,.01),rgba(3,9,18,.06));pointer-events:none}
"""
html = html.replace('</style></head><body>', hero_css + '</style></head><body>', 1)

data_uri = 'data:image/webp;base64,'
replacement = f'<div class="heroVisual"><img class="heroPhoto" src="{data_uri}" alt="Qrator Labs × FT Community"></div>'

patterns = [
    r'<div class="heroVisual"><svg.*?</svg><div class="priceBox">.*?</div></div>',
    r'<div class="heroVisual"><img class="heroPhoto"[^>]*><div class="priceBox">.*?</div></div>',
    r'<div class="heroVisual"><img class="heroPhoto"[^>]*></div>',
]

count = 0
for pattern in patterns:
    html, count = re.subn(pattern, replacement, html, count=1, flags=re.S)
    if count:
        break

if count != 1:
    raise SystemExit(f'Hero replacement count: {count}')

path.write_text(html, encoding='utf-8')
